from AlgorithmImports import *
from datetime import timedelta


class SpyBullishCrossoverOptions(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.Strikes(-500, 500).Expiration(0, 1000)
        )
        self.option_symbol = option.Symbol

        self.fast = RollingWindow[float](5)
        self.slow = RollingWindow[float](20)

        self.previous_fast = None
        self.previous_slow = None
        self.crossover_pending = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration = None
        self.expiration_processing_done = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        end = bar.EndTime

        # Equity data is regular-session data; retain this guard for safety.
        if end.time() < time(9, 35) or end.time() > time(16, 0):
            return

        prior_fast = self.fast[-1] if self.fast.IsReady else None
        prior_slow = self.slow[-1] if self.slow.IsReady else None

        self.fast.Add(bar.Close)
        self.slow.Add(bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = sum(self.fast[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow[i] for i in range(20)) / 20.0

        if prior_fast is not None and prior_slow is not None:
            bullish = (
                prior_fast <= prior_slow
                and current_fast > current_slow
            )

            if (
                bullish
                and time(9, 45) <= end.time() <= time(14, 30)
            ):
                self.crossover_pending = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing()

        if self.held_option is not None:
            self.EvaluateHeldOption(slice)

        if not self.crossover_pending:
            return

        # A signal is evaluated exactly once and is never queued.
        self.crossover_pending = False

        if self.held_option is not None:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
        ):
                return

        self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Expiry.date() >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def EvaluateHeldOption(self, slice):
        symbol = self.held_option
        holding = self.Portfolio[symbol]

        if not holding.Invested:
            return

        expiry_date = self.expiration.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.SubmitExit("Expiration protection")
            return

        if (
            self.IsTradingDayImmediatelyBeforeExpiry(today, expiry_date)
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("Pre-expiration time stop")
            return

        if symbol not in slice.OptionChains:
            # Continue searching all chains because the key may differ by
            # canonical symbol representation.
            contract = self.GetContractFromSlice(slice, symbol)
        else:
            contract = None

        if contract is None:
            contract = self.GetContractFromSlice(slice, symbol)

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def GetContractFromSlice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            if self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

    def HandleExpirationProcessing(self):
        if self.held_option is None:
            return

        if self.expiration_processing_done:
            return

        if self.Time.date() >= self.expiration.date():
            self.expiration_processing_done = True
            self.SubmitExit("Expiration processing protection")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]

        if holding.Invested:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.Liquidate(
                self.spy,
                tag="Unexpected exercise or assignment"
            )

    def IsTradingDayImmediatelyBeforeExpiry(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        probe = current_date + timedelta(days=1)

        while probe < expiry_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(probe):
                return False
            probe += timedelta(days=1)

        return probe == expiry_date

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration = self.Securities[
                    self.held_option
                ].Symbol.ID.Date
                self.expiration_processing_done = False

                self.Debug(
                    f"Entered {self.held_option} at filled price "
                    f"{self.entry_price:.4f}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exited {order_event.Symbol} at filled price "
                    f"{order_event.FillPrice:.4f}"
                )

                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_option = None
                    self.entry_price = None
                    self.expiration = None
                    self.exit_ticket = None
                    self.entry_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                f"Unexpected exercise or assignment for {order_event.Symbol}; "
                "liquidating resulting SPY position."
            )
            self.Liquidate(
                self.spy,
                tag="Unexpected exercise or assignment"
            )

        if order_event.Status == OrderStatus.Invalid:
            self.Debug(
                f"Order invalid for {order_event.Symbol}: "
                f"{order_event.Message}"
            )

        if order_event.Status == OrderStatus.Canceled:
            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_ticket = None
