from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import deque


class SpyBullishOptionAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self._minute_groups = {}
        self._latest_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_liquidated = set()
        self.assignment_handled_dates = set()

    def OnData(self, slice: Slice):
        self._latest_slice = slice

        # Immediately remove any SPY equity created by exercise or assignment.
        equity_quantity = self.Portfolio[self.spy].Quantity
        if equity_quantity != 0:
            self.Debug(
                f"Unexpected exercise/assignment handling: liquidating "
                f"{equity_quantity} SPY shares at {self.Time}"
            )
            self.MarketOrder(self.spy, -equity_quantity)
            self.assignment_handled_dates.add(self.Time.date())

        self._process_expiration_safety()
        self._process_time_stop(slice)
        self._process_profit_target(slice)

        if self.spy in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy])

    def _process_minute_bar(self, bar: TradeBar):
        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        # Regular-session minute bars ending from 09:31 through 16:00.
        if not (time(9, 31) <= local_end.time() <= time(16, 0)):
            return

        bucket_minute = ((local_end.minute // 5) + 1) * 5
        bucket_date = local_end.date()

        if bucket_minute >= 60:
            bucket_end = datetime(
                bucket_date,
                local_end.time().replace(hour=local_end.hour + 1,
                                         minute=0,
                                         second=0,
                                         microsecond=0)
            )
        else:
            bucket_end = datetime(
                bucket_date,
                local_end.time().replace(minute=bucket_minute,
                                         second=0,
                                         microsecond=0)
            )

        # Only use regular-session five-minute bars.
        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        key = bucket_end
        group = self._minute_groups.setdefault(key, [])
        group.append(bar)

        if len(group) < 5:
            return

        if len(group) > 5:
            del self._minute_groups[key]
            return

        bars = sorted(group, key=lambda x: x.EndTime)
        del self._minute_groups[key]

        consolidated = TradeBar(
            symbol=self.spy,
            time=bars[0].Time,
            end_time=bars[-1].EndTime,
            open=bars[0].Open,
            high=max(x.High for x in bars),
            low=min(x.Low for x in bars),
            close=bars[-1].Close,
            volume=sum(x.Volume for x in bars)
        )

        self._on_five_minute_bar(consolidated)

    def _on_five_minute_bar(self, bar: TradeBar):
        close = float(bar.Close)

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(list(self.fast_values)[-5:]) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime
        if bar_end.tzinfo is not None:
            bar_end = bar_end.replace(tzinfo=None)

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish and eligible_time:
            self._try_enter()

    def _try_enter(self):
        if self._has_option_holding() or self._entry_is_open():
            return

        if self._latest_slice is None or self.spy not in self._latest_slice.OptionChains:
            self.Debug(f"Skipped entry: no option chain at {self.Time}")
            return

        chain = self._latest_slice.OptionChains[self.spy]
        algorithm_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right in (OptionRight.Call, OptionRight.Put)
            and (contract.Expiry.date() - algorithm_date).days >= 7
        })

        if not expirations:
            self.Debug(f"Skipped entry: no expiration satisfies rule at {self.Time}")
            return

        selected_expiration = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right in (OptionRight.Call, OptionRight.Put)
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no eligible contract for "
                f"{selected_expiration} at {self.Time}"
            )
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        contract = candidates[0]

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(f"Entry submitted: {contract.Symbol} at {self.Time}")

    def _process_profit_target(self, slice: Slice):
        if not self._has_option_holding() or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self._order_is_closed(self.exit_ticket):
            return

        contract = None
        if self.spy in slice.OptionChains:
            for candidate in slice.OptionChains[self.spy]:
                if candidate.Symbol == self.held_option:
                    contract = candidate
                    break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            quantity = self.Portfolio[self.held_option].Quantity
            if quantity != 0:
                self._cancel_open_exit()
                self.exit_ticket = self.MarketOrder(
                    self.held_option,
                    -quantity
                )
                self.Debug(
                    f"Profit-target exit submitted: {self.held_option}, "
                    f"midpoint={midpoint:.4f}, entry={self.entry_price:.4f}"
                )

    def _process_time_stop(self, slice: Slice):
        if not self._has_option_holding():
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if self.Time.date() != previous_trading_day:
            return

        if self.Time.time() < time(15, 45):
            return

        if self.exit_ticket is not None and not self._order_is_closed(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self._cancel_open_exit()
            self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
            self.Debug(f"Time-stop exit submitted: {self.held_option}")

    def _process_expiration_safety(self):
        if not self._has_option_holding():
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        if self.Time.date() < expiry:
            return

        if expiry in self.expiration_liquidated:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self._cancel_open_exit()
            self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
            self.Debug(
                f"Expiration safety liquidation submitted: "
                f"{self.held_option}"
            )

        self.expiration_liquidated.add(expiry)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        symbol = order_event.Symbol

        if self.entry_ticket is not None and symbol == self.entry_ticket.Symbol:
            if order_event.FillQuantity > 0:
                self.held_option = symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {symbol}, price={self.entry_price:.4f}"
                )

        if self.exit_ticket is not None and symbol == self.exit_ticket.Symbol:
            if self.Portfolio[symbol].Quantity == 0:
                self.Debug(f"Exit filled: {symbol}")
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                f"Unexpected assignment received; liquidating SPY position "
                f"of {quantity}"
            )
            self.MarketOrder(self.spy, -quantity)

    def _has_option_holding(self):
        return (
            self.held_option is not None and
            self.Portfolio[self.held_option].Quantity != 0
        )

    def _entry_is_open(self):
        return (
            self.entry_ticket is not None and
            not self._order_is_closed(self.entry_ticket)
        )

    @staticmethod
    def _order_is_closed(ticket):
        return ticket.Status in (
            OrderStatus.Filled,
