            self.bucket_end = bucket_end
        elif bucket_end != self.bucket_end:
            completed = None
            if len(self.bucket_bars) == 5:
                completed = self._build_completed_bar(self.bucket_bars)

            self.bucket_bars = []
            self.bucket_end = bucket_end

            if completed is not None:
                self.last_five_minute_end = completed.EndTime

                if self._bullish_crossover(completed):
                    self._try_entry(slice, completed)

        self.bucket_bars.append(bar)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_option = self.entry_ticket.Symbol
                self.Debug(
                    f"Entry filled: {self.held_option} at "
                    f"{self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled,
            ):
                if order_event.Status != OrderStatus.PartiallyFilled:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_option}")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

    def _is_regular_session_minute(self, time):
        t = time.time()
        return time.weekday() < 5 and t >= time(9, 31) and t <= time(16, 0)

    def _bucket_end(self, time):
        minute = (time.minute // 5 + 1) * 5
        if minute >= 60:
            return time.replace(
                hour=time.hour + 1,
                minute=minute - 60,
                second=0,
                microsecond=0,
            )
        return time.replace(minute=minute, second=0, microsecond=0)

    def _build_completed_bar(self, bars):
        first = bars[0]
        last = bars[-1]

        return TradeBar(
            self.bucket_end - timedelta(minutes=5),
            self.spy,
            first.Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            last.Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5),
        )

    def _bullish_crossover(self, bar):
        self.fast_closes.append(bar.Close)
        self.slow_closes.append(bar.Close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return False

        fast_current = sum(list(self.fast_closes)[-5:]) / 5.0
        slow_current = sum(self.slow_closes) / 20.0

        if len(self.fast_closes) < 6:
            return False

        fast_previous = sum(list(self.fast_closes)[-6:-1]) / 5.0
        slow_previous = (
            sum(list(self.slow_closes)[:-1]) / 20.0
        )

        end_time = bar.EndTime
        eligible_time = end_time.time() >= datetime.time(9, 45) and \
            end_time.time() <= datetime.time(14, 30)

        return (
            eligible_time
            and fast_previous <= slow_previous
            and fast_current > slow_current
        )

    def _try_entry(self, slice, bar):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            return

        chain = slice.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug(f"Skipped entry at {bar.EndTime}: no option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"Skipped entry at {bar.EndTime}: invalid SPY price.")
            return

        min_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= min_expiry
        })

        if not expirations:
            self.Debug(
                f"Skipped entry at {bar.EndTime}: no expiration at least "
                "seven calendar days away."
            )
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry at {bar.EndTime}: no qualifying call contract."
            )
            return

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike:.2f}"
        )

    def _process_option_exit(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        contract = slice.OptionChains.get(self.option_canonical)
        quote = None

        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_option:
                    quote = item
                    break

        if quote is None or quote.BidPrice <= 0 or quote.AskPrice <= 0:
            return

        midpoint = (quote.BidPrice + quote.AskPrice) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(
                self.exit_ticket.OrderId,
                "Profit target reached"
            )
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -holding.Quantity,
            tag="50 percent profit target"
        )
        self.Debug(
            f"Profit target reached for {self.held_option}; "
            f"midpoint {midpoint:.4f}"
        )

    def _process_option_expiration(self):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        expiry = self.Securities[self.held_option].Symbol.ID.Date.date()
        current_date = self.Time.date()

        # Never intentionally carry the contract into expiration.
        if current_date >= expiry:
            self.no_entry_date = current_date
            self._submit_exit("Expiration liquidation")

        # Scheduled liquidation at 15:45 on the preceding trading day.
        elif current_date == expiry - timedelta(days=1) and \
                self.Time.time() >= datetime.time(15, 45):
            if current_date not in self.time_stop_submitted_for:
                self.time_stop_submitted_for.add(current_date)
                self._submit_exit("Pre-expiration time stop")

    def _submit_exit(self, tag):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self.exit_ticket is not None:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -holding.Quantity,
            tag=tag
        )
        self.Debug(f"Exit submitted for {self.held_option}: {tag}")

