        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def ProcessExpirationTimeStop(self):
        if self.held_symbol is None or self.expiration is None:
            return

        if self.Time.date() >= self.expiration:
            if not self.expiration_protection_sent:
                self.expiration_protection_sent = True
