            self.ClearPositionState()
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {reason}")

    def HandleUnexpectedEquity(self):
        holding = self.Portfolio[self.spy]

        if holding.Invested:
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY equity"
            )
            self.Liquidate(
                self.spy,
                tag="exercise or assignment handling"
            )

